import{_ as n,l as r,o as e,c as o,v as t,p as l,x as s,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"分布式 OS 直觉","description":"","frontmatter":{"title":"分布式 OS 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-os-intuition.md","filePath":"cs/distributed-os-intuition.md","lastUpdated":1789023840000}'),h={name:"cs/distributed-os-intuition.md"};function u(m,a,S,E,f,_){const i=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="分布式-os-直觉" tabindex="-1">分布式 OS 直觉 <a class="header-anchor" href="#分布式-os-直觉" aria-label="Permalink to &quot;分布式 OS 直觉&quot;">​</a></h1><div class="epigraph"><p>分布式操作系统试图让多机共享同一套进程与文件抽象；网络分区与延迟使「单机 POSIX」无法透明延伸，于是实践退回显式 RPC、集群与容器编排。</p><footer>—— 据 Tanenbaum and Van Steen, <em>Distributed Systems</em>；[NFS 语义](/cs/nfs-semantics) 为已见裂缝</footer></div><p><a href="/cs/windows-nt-contrast">NT 对照</a> 仍是单机。<a href="/cs/nfs-semantics">NFS</a> 已削弱 POSIX。<a href="/cs/live-migration">热迁移</a> 搬的是整台 VM。缺口是 <strong>为何没有透明分布式 Unix</strong>：直觉封口操作系统进阶。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Amoeba、Sprite、Plan 9 曾把资源当网络上的名字。缺口：CAP 式权衡（本课不重开分布式课全文）——延迟、分区、身份。Linux 实践：单机内核 + 用户态编排（k8s）+ 显式 RPC。本课不发明论文编号，不写编排教程。</p><p><span class="marginnote">单系统映像 SSI 集群存在，失败模式仍是网络。对象是抽象能不能透明，不是具体中间件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 NFS close-to-open：已是不透明。对照 <a href="/cs/netns-veth">netns</a>：隔离不合并多机。对照 <a href="/cs/rdma-os">RDMA</a>：快路径仍要显式 verbs。对照 seL4：证明停在单核/单机假设。</p>',8)),(e(),l(p,null,{default:s(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20WANT%5B%22%E9%80%8F%E6%98%8E%E5%8D%95%E7%B3%BB%E7%BB%9F%E6%98%A0%E5%83%8F%22%5D%20--%3E%20NET%5B%22%E5%BB%B6%E8%BF%9F%E4%B8%8E%E5%88%86%E5%8C%BA%22%5D%0A%20%20NET%20--%3E%20CRACK%5B%22POSIX%20%E8%AF%AD%E4%B9%89%E8%A3%82%E7%BC%9D%22%5D%0A%20%20CRACK%20--%3E%20EXP%5B%22%E6%98%BE%E5%BC%8F%20RPC%20%E4%B8%8E%E7%BC%96%E6%8E%92%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>OS 进阶课把单机栈从 FAT 讲到微内核与 VMM；分布式「同一 OS」在网络上裂开，必须换接口。这不是失败，是边界：后课若进网络/数据库栏，从显式协议开始，不假装 <code>read</code> 跨机仍瞬时一致。不要写成量化撮合集群。与 <a href="/cs/fsync">fsync</a>：持久是单设备故事；跨机要复制协议。</p><p>Plan 9 的 9P 仍有 virtio-fs 回声——显式协议，不是魔法透明。</p><p>实现上：Plan 9 的 9P 把一切当文件，但仍是显式协议，断线有错误。SSI 集群在分区时必须选脑裂策略。编排系统接受不透明，换来可推理的失败。 读法上只引用<a href="/cs/windows-nt-contrast">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>分布式 OS 直觉</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入全部 SSI 项目。不保证未来 CXL 内存池改变边界——那仍要新一致性课。操作系统进阶到此：布局、块、包、页、调度、启动、观测、虚拟化与形态都已钉住。</p><p>版本字段会变，课序钉的是机制对象「分布式 OS 直觉」，不是某一主线内核的结构体名。 后课默认：单机 OS 抽象不透明扩展到分区网络。操作系统进阶在此封口；下一课程从<a href="/cs/shannon-capacity-link">香农容量在链路</a>起计算机网络进阶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>透明分布式 Unix 被延迟与分区挡住。</li><li>实践是单机内核加显式网络与编排。</li><li>操作系统进阶课序到此结束；下一课香农容量。</li><li>出处：Tanenbaum <em>Distributed Systems</em>；NFS；Plan 9/9P 背景。</li></ul>',11))])}const b=n(h,[["render",u]]);export{B as __pageData,b as default};
